import std.io

pub type NumErr = Bad(Int64)

record Fetcher { seed: Int64 }

impl Fetcher {
    fn fetch(self) -> Result<Int64, NumErr> {
        return Ok(self.seed)
    }
}

pub fn main() effect io -> Result<(), NumErr> {
    let f = Fetcher { seed: 7 }
    let v = f.fetch()?
    io.println("v ${v}")
    return Ok(())
}
